{* Code generated by xgen. DO NOT EDIT.
    Source: xgen/specs/organisms/product-card.json
    A product as a card: picture, optional badge, category, name, rating, summary, price and an add button. Axes: layout (vertical, horizontal), media (image, none), ratio, rating (show, hide), action (button, none), density.
    Props (p): product, labels, badges, layout, media, ratio, rating, action, density. *}
{var $v_product = ($p['product'] ?? null)}
{var $v_labels = ($p['labels'] ?? null)}
{var $v_badges = ($p['badges'] ?? null)}
{var $v_layout = ($p['layout'] ?? 'vertical')}
{var $v_media = ($p['media'] ?? 'image')}
{var $v_ratio = ($p['ratio'] ?? '4/3')}
{var $v_rating = ($p['rating'] ?? 'show')}
{var $v_action = ($p['action'] ?? 'button')}
{var $v_density = ($p['density'] ?? 'default')}
{capture $c_12}
  {if ui_t(ui_eq($v_media, 'image'))}
    {capture $c_2}
      {=ui_include('blocks/media-frame.latte', ['p' => ['alt' => ui_get($v_product, ['name']), 'ratio' => $v_ratio, 'className' => ui_cnv(['h-full'])]])|noescape}
      {if ui_t(ui_get($v_product, ['badge']))}
        {capture $c_1}
          {=ui_text(ui_at($v_badges, ui_get($v_product, ['badge'])))}
        {/capture}
        {=ui_include('ui/badge/badge.latte', ['p' => ['Variant' => 'default', 'Size' => 'default', 'Class' => 'absolute left-4 top-4', 'Attrs' => ui_attrs(['data-testid', 'badge'])], 'children' => $c_1])|noescape}
      {/if}
    {/capture}
    {=ui_include('ui/box/box.latte', ['p' => ['Class' => ui_s(ui_cnv(['relative shrink-0', (ui_t(ui_eq($v_layout, 'horizontal')) ? 'sm:w-48' : '')]))], 'children' => $c_2])|noescape}
  {/if}
  {capture $c_11}
    {capture $c_3}
      {=ui_text(ui_get($v_product, ['category']))}
    {/capture}
    {=ui_include('ui/text/text.latte', ['p' => ['Size' => 'xs', 'Class' => 'uppercase tracking-wide text-muted-foreground'], 'children' => $c_3])|noescape}
    {capture $c_4}
      {=ui_text(ui_get($v_product, ['name']))}
    {/capture}
    {=ui_include('ui/title/title.latte', ['p' => ['As' => ui_i(3), 'Size' => 'base', 'Weight' => 'bold'], 'children' => $c_4])|noescape}
    {if ui_t(ui_eq($v_rating, 'show'))}
      {capture $c_6}
        {=ui_include('blocks/rating.latte', ['p' => ['value' => ui_get($v_product, ['rating']), 'label' => ui_tpl(ui_get($v_labels, ['ratingLabel']), [ui_get($v_product, ['rating'])])]])|noescape}
        {capture $c_5}
          {=ui_text(ui_tpl(ui_get($v_labels, ['reviews']), [ui_get($v_product, ['reviews'])]))}
        {/capture}
        {=ui_include('ui/text/text.latte', ['p' => ['Size' => 'xs', 'Class' => 'text-muted-foreground'], 'children' => $c_5])|noescape}
      {/capture}
      {=ui_include('ui/group/group.latte', ['p' => ['Gap' => '2'], 'children' => $c_6])|noescape}
    {/if}
    {if ui_t(ui_eq($v_density, 'default'))}
      {capture $c_7}
        {=ui_text(ui_get($v_product, ['summary']))}
      {/capture}
      {=ui_include('ui/text/text.latte', ['p' => ['Size' => 'sm', 'Class' => 'text-muted-foreground'], 'children' => $c_7])|noescape}
    {/if}
    {capture $c_10}
      {capture $c_8}
        {=ui_text(ui_money(ui_get($v_product, ['price']), ui_get($v_product, ['currency'])))}
      {/capture}
      {=ui_include('ui/text/text.latte', ['p' => ['Size' => 'xl', 'Weight' => 'bold'], 'children' => $c_8])|noescape}
      {if ui_t(ui_eq($v_action, 'button'))}
        {capture $c_9}
          {=ui_text((ui_t(ui_get($v_product, ['inStock'])) ? ui_get($v_labels, ['add']) : ui_get($v_labels, ['soldOut'])))}
        {/capture}
        {=ui_include('ui/button/button.latte', ['p' => ['Variant' => ui_s((ui_t(ui_get($v_product, ['inStock'])) ? 'default' : 'outline')), 'Size' => 'sm', 'Disabled' => ui_t(!(ui_t(ui_get($v_product, ['inStock'])))), 'Attrs' => ui_attrs(['data-testid', 'add'])], 'children' => $c_9])|noescape}
      {/if}
    {/capture}
    {=ui_include('ui/group/group.latte', ['p' => ['Gap' => '4', 'Justify' => 'between', 'Class' => 'mt-auto pt-2'], 'children' => $c_10])|noescape}
  {/capture}
  {=ui_include('ui/card/card-content.latte', ['p' => ['Class' => 'flex flex-1 flex-col gap-2'], 'children' => $c_11])|noescape}
{/capture}
{=ui_include('ui/block/block.latte', ['p' => ['Tag' => 'article', 'Class' => ui_s(ui_cnv(['flex flex-col gap-8 bg-card p-6 text-card-foreground inset-ring inset-ring-border rounded', 'h-full gap-4 overflow-hidden', (ui_t(ui_eq($v_layout, 'horizontal')) ? 'flex flex-col sm:flex-row' : 'flex flex-col')])), 'Attrs' => ui_attrs(['data-slot', 'card', 'data-testid', 'item', 'data-layout', $v_layout])], 'children' => $c_12])|noescape}
